import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S08/S08E09.html","title":"S08E09 The One with the Rumor","lang":"zh-CN","frontmatter":{"title":"S08E09 The One with the Rumor","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":179},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":3}]},"readingTime":{"minutes":34.03,"words":10208},"filePathRelative":"语言/英语/Friends老友记/S08/S08E09.md"}`),l={name:`S08E09.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-with-the-rumor" tabindex="-1"><a class="header-anchor" href="#the-one-with-the-rumor"><span>The One with the Rumor</span></a></h1><blockquote><p><em>有谣言的那个</em></p></blockquote><p>The One With The Rumor</p><blockquote><p>有谣言的那个</p></blockquote><p><strong>Written by: Shana Goldberg-Meehan</strong></p><blockquote><p>作者：沙娜·戈德伯格·米汉</p></blockquote><p><strong>Transcribed by: Eric Aasen</strong></p><blockquote><p>转录人：埃里克·艾森</p></blockquote><hr><p>🎬 <em>Joey and Rachel&#39;s, Joey is reading What to Expect When You’re Expecting as Rachel enters from her bedroom.</em></p><blockquote><p>🎬 <em>乔伊和瑞秋的，当瑞秋从她的卧室进入时，乔伊正在读你期待的东西。</em></p></blockquote>`,11),r(p,{src:`/audio/friends/S08/S08E09/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[3]||=i(` Hey Rach listen, did you know that during pregnancy your fingers swell up to twice their size and never go back.`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`嘿，瑞秋，听着，你知道吗，在怀孕期间，你的手指会肿到原来的两倍大，再也不会回去了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`Rachel Green:`,-1),c[7]||=i(` (looking at her fingers) Oh my…God! Let me see that! (Grabs the book from him.)`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`（看着她的手指）哦，天哪！让我看看！（从他手里接过那本书。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/003.mp3`}),c[9]||=i(),c[10]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[11]||=i(` (laughing) You fall for it every time!`,-1),c[12]||=a(`blockquote`,null,[a(`p`,null,`（笑）你每次都会上当！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/004.mp3`}),c[13]||=i(),c[14]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[15]||=i(` (entering) Hey!`,-1),c[16]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/005.mp3`}),c[17]||=i(),c[18]||=a(`strong`,null,`Rachel Green:`,-1),c[19]||=i(` Hi!`,-1),c[20]||=a(`blockquote`,null,[a(`p`,null,`嗨！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/006.mp3`}),c[21]||=i(),c[22]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[23]||=i(` I brought you my old maternity clothes! (Sets a bag on the counter.)`,-1),c[24]||=a(`blockquote`,null,[a(`p`,null,`我给你带来了我的旧孕妇装！（在柜台上放一个袋子。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/007.mp3`}),c[25]||=i(),c[26]||=a(`strong`,null,`Rachel Green:`,-1),c[27]||=i(` Oh Pheebs that’s so sweet—(Grabs a pair of pants)—Ooh, those are so cute!`,-1),c[28]||=a(`blockquote`,null,[a(`p`,null,`哦，菲比，太可爱了-（抓起一条裤子）-哦，那些太可爱了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/008.mp3`}),c[29]||=i(),c[30]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[31]||=i(` Yeah! And look, (Grabs the pants) see how they expand as the baby grows? (There’s a stretchy part in front.) And then after the baby’s born, they’re great for shoplifting melons.`,-1),c[32]||=a(`blockquote`,null,[a(`p`,null,`是啊！看，（抓着裤子）看看它们是如何随着婴儿的成长而膨胀的？（前面有一个有弹性的部分。）婴儿出生后，它们非常适合在商店偷瓜。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/009.mp3`}),c[33]||=i(),c[34]||=a(`strong`,null,`Monica Geller:`,-1),c[35]||=i(` (entering) Oh good you’re all here. Thanksgiving tomorrow, four o’clock. (To Rachel) Oh, guess who I invited. Remember that guy Will Colbert from high school?`,-1),c[36]||=a(`blockquote`,null,[a(`p`,null,`（进来）哦，很好，你们都来了。明天感恩节，四点钟。（对瑞秋）哦，猜猜我邀请了谁。还记得高中的威尔·科尔伯特吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/010.mp3`}),c[37]||=i(),c[38]||=a(`strong`,null,`Rachel Green:`,-1),c[39]||=i(` No.`,-1),c[40]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/011.mp3`}),c[41]||=i(),c[42]||=a(`strong`,null,`Monica Geller:`,-1),c[43]||=i(` He was in Ross’s class…marching band…kinda overweight? Well, really overweight. I mean I was his thin friend.`,-1),c[44]||=a(`blockquote`,null,[a(`p`,null,`他在罗斯的班上……游行乐队……有点超重？嗯，真的超重了。我是说我是他的瘦朋友。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/012.mp3`}),c[45]||=i(),c[46]||=a(`strong`,null,`Rachel Green:`,-1),c[47]||=i(` Wow! I don’t remember him. Honey, are you sure you’re not talking about your imaginary boyfriend.`,-1),c[48]||=a(`blockquote`,null,[a(`p`,null,`哇！我不记得他了。亲爱的，你确定你说的不是你想象中的男朋友吗。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/013.mp3`}),c[49]||=i(),c[50]||=a(`strong`,null,`Monica Geller:`,-1),c[51]||=i(` No that was Jarred! Wow! I haven’t thought about him in a long time… (Stares off into the distance lost in thought.) (Pause) Anyway, umm Will’s, Will’s here on business and he didn’t have a place to go so I invited him here.`,-1),c[52]||=a(`blockquote`,null,[a(`p`,null,`不，那太不和谐了！哇！我好久没想他了……（凝视着远处陷入沉思。）（停顿）不管怎样，嗯，威尔，威尔来这里出差，他没有地方去，所以我邀请他来这里。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/014.mp3`}),c[53]||=i(),c[54]||=a(`strong`,null,`Rachel Green:`,-1),c[55]||=i(` Oh that’s nice.`,-1),c[56]||=a(`blockquote`,null,[a(`p`,null,`哦，太好了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/015.mp3`}),c[57]||=i(),c[58]||=a(`strong`,null,`Monica Geller:`,-1),c[59]||=i(` Oh, and by the way, he’s lost a bunch of weight. I mean he looks goo-ood! Okay, I mean really, really gorgeous! (Joey clears his throat.) I still love Chandler.`,-1),c[60]||=a(`blockquote`,null,[a(`p`,null,`哦，顺便说一句，他瘦了不少。我是说他看起来很好！好吧，我是说真的，真的很漂亮！（乔伊清了清嗓子）我仍然爱钱德勒。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/016.mp3`}),c[61]||=i(),c[62]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[63]||=i(` I just want you to say it once in a while.`,-1),c[64]||=a(`blockquote`,null,[a(`p`,null,`我只是想让你偶尔说一次。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/017.mp3`}),c[65]||=i(),c[66]||=a(`strong`,null,`Monica Geller:`,-1),c[67]||=i(` All right okay, just so you know, I’m not gonna make a turkey this year.`,-1),c[68]||=a(`blockquote`,null,[a(`p`,null,`好吧，你知道，我今年不会做火鸡。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/018.mp3`}),c[69]||=i(),c[70]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[71]||=i(` What?!`,-1),c[72]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/019.mp3`}),c[73]||=i(),c[74]||=a(`strong`,null,`Monica Geller:`,-1),c[75]||=i(` Well Phoebe doesn’t eat turkey…`,-1),c[76]||=a(`blockquote`,null,[a(`p`,null,`菲比不吃火鸡…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/020.mp3`}),c[77]||=i(),c[78]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[79]||=i(` Phoebe!`,-1),c[80]||=a(`blockquote`,null,[a(`p`,null,`菲比！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/021.mp3`}),c[81]||=i(),c[82]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[83]||=i(` Turkey’s are beautiful, intelligent animals!`,-1),c[84]||=a(`blockquote`,null,[a(`p`,null,`火鸡是美丽、聪明的动物！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/022.mp3`}),c[85]||=i(),c[86]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[87]||=i(` No they’re not! They’re ugly and stupid and delicious!`,-1),c[88]||=a(`blockquote`,null,[a(`p`,null,`不，他们不是！它们又丑又笨又好吃！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/023.mp3`}),c[89]||=i(),c[90]||=a(`strong`,null,`Monica Geller:`,-1),c[91]||=i(` All right! Okay, it’s just Phoebe. Will’s still on a diet, Chandler doesn’t eat Thanksgiving food, and Rachel’s having her aversion to poultry.`,-1),c[92]||=a(`blockquote`,null,[a(`p`,null,`好吧！好吧，我只是菲比。威尔还在节食，钱德勒不吃感恩节食物，瑞秋讨厌吃家禽。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/024.mp3`}),c[93]||=i(),c[94]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[95]||=i(` She is?`,-1),c[96]||=a(`blockquote`,null,[a(`p`,null,`是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/025.mp3`}),c[97]||=i(),c[98]||=a(`strong`,null,`Rachel Green:`,-1),c[99]||=i(` Remember I had to leave the room the other day when you had that roast chicken?`,-1),c[100]||=a(`blockquote`,null,[a(`p`,null,`记得那天你吃烤鸡的时候我不得不离开房间吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/026.mp3`}),c[101]||=i(),c[102]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[103]||=i(` Yeah. But I thought that was because I put the whole thing on my hand and made it walk across the table.`,-1),c[104]||=a(`blockquote`,null,[a(`p`,null,`是的。但我想那是因为我把整个东西都放在我的手上，让它穿过桌子。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/027.mp3`}),c[105]||=i(),c[106]||=a(`strong`,null,`Monica Geller:`,-1),c[107]||=i(` Anyway, it just doesn’t seem worth it to make a whole turkey for just three people. Okay? It’s a lot of work.`,-1),c[108]||=a(`blockquote`,null,[a(`p`,null,`不管怎样，仅仅为三个人做一整只火鸡似乎不值得。可以这是一项艰巨的工作。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/028.mp3`}),c[109]||=i(),c[110]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[111]||=i(` But you gotta have turkey on Thanksgiving! I mean, Thanksgiving with no turkey is like-like Fourth of July with no apple pie! Or Friday with no two pizzas!`,-1),c[112]||=a(`blockquote`,null,[a(`p`,null,`但是感恩节你得吃火鸡！我的意思是，没有火鸡的感恩节就像没有苹果派的七月四日！或者星期五没有两个比萨饼！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/029.mp3`}),c[113]||=i(),c[114]||=a(`strong`,null,`Monica Geller:`,-1),c[115]||=i(` All right fine! If it means that much to you! But just—there’s gonna be a ton left over.`,-1),c[116]||=a(`blockquote`,null,[a(`p`,null,`好吧，很好！如果它对你有那么大的意义！但只剩下一吨了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/030.mp3`}),c[117]||=i(),c[118]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[119]||=i(` No there won’t! I promise I will finish that turkey!`,-1),c[120]||=a(`blockquote`,null,[a(`p`,null,`不，不会的！我保证我会吃完那只火鸡！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/031.mp3`}),c[121]||=i(),c[122]||=a(`strong`,null,`Monica Geller:`,-1),c[123]||=i(` All right, you’re telling me you can eat an entire turkey in just one sitting?`,-1),c[124]||=a(`blockquote`,null,[a(`p`,null,`好吧，你是说你一次就能吃下一整只火鸡？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/032.mp3`}),c[125]||=t(` <strong>Joey Tribbiani:</strong> That’s right! ‘Cause I’m a Tribbiani! (To Rachel) And this is what we do! I mean we may not be great thinkers or world leaders, we don’t read a lot or run very fast, but damnit! We can eat!<blockquote><p>没错因为我是Tribbiani！（对瑞秋）这就是我们要做的！我的意思是，我们可能不是伟大的思想家或世界领袖，我们读书不多，跑得也不快，但该死！我们可以吃！</p></blockquote><p>Opening Credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Chandler is watching football, and it’s actually the right game Green Bay at Detroit (although not this year’s), as Monica is getting everything ready.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒家，钱德勒正在看足球比赛，实际上这是底特律绿湾的比赛（虽然不是今年的），因为莫妮卡正在准备一切。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E09/033.mp3`}),c[126]||=i(),c[127]||=a(`strong`,null,`Monica Geller:`,-1),c[128]||=i(` Hey, isn’t weird to think about how next year at this time they’ll be a little baby at the table? (Chandler turns around in horror.) (Seeing him) Rachel’s! But good to know where you’re at!`,-1),c[129]||=a(`blockquote`,null,[a(`p`,null,`嘿，想想明年这个时候他们会变成餐桌上的小婴儿，这不是很奇怪吗？（钱德勒惊恐地转过身。）（看到他）瑞秋的！但很高兴知道你在哪里！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/034.mp3`}),c[130]||=i(),c[131]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[132]||=i(` (entering) Hey!`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,`（进来）嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/035.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`Monica Geller:`,-1),c[136]||=i(` Hey!`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/036.mp3`}),c[138]||=i(),c[139]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[140]||=i(` Happy Thanksgiving!`,-1),c[141]||=a(`blockquote`,null,[a(`p`,null,`感恩节快乐！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/037.mp3`}),c[142]||=i(),c[143]||=a(`strong`,null,`Monica Geller:`,-1),c[144]||=i(` You too!`,-1),c[145]||=a(`blockquote`,null,[a(`p`,null,`你也是！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/038.mp3`}),c[146]||=i(),c[147]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[148]||=i(` Anything I can do to help?`,-1),c[149]||=a(`blockquote`,null,[a(`p`,null,`有什么我能帮忙的吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/039.mp3`}),c[150]||=i(),c[151]||=a(`strong`,null,`Monica Geller:`,-1),c[152]||=i(` Actually there is. Chandler usually helps me with this, but he’s really into the game so I don’t want to bother him. Could you help me fold these napkins? (Hands her a stack of them.)`,-1),c[153]||=a(`blockquote`,null,[a(`p`,null,`事实上有。钱德勒通常会帮我，但他很喜欢这个游戏，所以我不想打扰他。你能帮我叠这些餐巾吗？（递给她一叠。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/040.mp3`}),c[154]||=i(),c[155]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[156]||=i(` Sure!`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,`当然！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/041.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`Monica Geller:`,-1),c[160]||=i(` I’m gonna go across the hall to check on the yams.`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`我要穿过大厅去看看山药。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/042.mp3`}),c[162]||=i(),c[163]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[164]||=i(` Okay. (She starts folding the napkins in half.)`,-1),c[165]||=a(`blockquote`,null,[a(`p`,null,`好的。（她开始把餐巾对折。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/043.mp3`}),c[166]||=i(),c[167]||=a(`strong`,null,`Monica Geller:`,-1),c[168]||=i(` No! No! No! No sweetie! No! Not like that! We’re not at a barn dance. You’ve gotta—you wanna fold them like swans. Like I showed you at Christmas time, remember?`,-1),c[169]||=a(`blockquote`,null,[a(`p`,null,`不！不不不，亲爱的！不不是那样的！我们不是在谷仓舞会上。你得把它们像天鹅一样叠起来。就像我在圣诞节给你看的，记得吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/044.mp3`}),c[170]||=i(),c[171]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[172]||=i(` Yeah, it all just came screaming back to me. (Monica exits.) (To Chandler) So how’s the game?`,-1),c[173]||=a(`blockquote`,null,[a(`p`,null,`是啊，这一切都在我脑海里尖叫。（莫妮卡退出。）（对钱德勒）比赛怎么样？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/045.mp3`}),c[174]||=i(),c[175]||=a(`strong`,null,`Chandler Bing:`,-1),c[176]||=i(` I have no idea.`,-1),c[177]||=a(`blockquote`,null,[a(`p`,null,`我不知道。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/046.mp3`}),c[178]||=i(),c[179]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[180]||=i(` What?`,-1),c[181]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/047.mp3`}),c[182]||=i(),c[183]||=a(`strong`,null,`Chandler Bing:`,-1),c[184]||=i(` Yeah! I’m just pretending to watch the game so I don’t have to help out with stuff.`,-1),c[185]||=a(`blockquote`,null,[a(`p`,null,`是啊！我只是假装看比赛，所以我不需要帮忙。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/048.mp3`}),c[186]||=i(),c[187]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[188]||=i(` I don’t believe you! That is…brilliant! And Monica has no idea?`,-1),c[189]||=a(`blockquote`,null,[a(`p`,null,`我不相信你！真是……太棒了！莫妮卡不知道？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/049.mp3`}),c[190]||=i(),c[191]||=a(`strong`,null,`Chandler Bing:`,-1),c[192]||=i(` Nope! Every once and a while I just scream stuff at the TV.`,-1),c[193]||=a(`blockquote`,null,[a(`p`,null,`不！每隔一段时间我都会对着电视尖叫。`)],-1),c[194]||=a(`p`,null,[a(`em`,null,`(Monica enters and Chandler screams stuff at the TV.)`)],-1),c[195]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡进来，钱德勒对着电视尖叫。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/050.mp3`}),c[196]||=i(),c[197]||=a(`strong`,null,`Monica Geller:`,-1),c[198]||=i(` Is your team winning hon?`,-1),c[199]||=a(`blockquote`,null,[a(`p`,null,`你的球队赢了吗，亲爱的？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/051.mp3`}),c[200]||=i(),c[201]||=a(`strong`,null,`Chandler Bing:`,-1),c[202]||=i(` Yeah! Anderson just scored again! (To Phoebe) There’s no Anderson.`,-1),c[203]||=a(`blockquote`,null,[a(`p`,null,`是啊！安德森又进球了！（对菲比）没有安德森。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/052.mp3`}),c[204]||=i(),c[205]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[206]||=i(` Well I want to get in on this. Hey Mon? I don’t think I can help you after all, I didn’t realize this game was on.`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`嗯，我想参与进来。嘿，妈妈？我想我帮不了你毕竟，我不知道这场比赛已经开始了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/053.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`Monica Geller:`,-1),c[210]||=i(` Oh, I didn’t know you liked football.`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`哦，我不知道你喜欢足球。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/054.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[214]||=i(` Well normally I don’t, but y’know…(looks at the TV)…Green Bay is playing.`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`通常我不知道，但你知道…（看电视）…绿湾在演奏。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/055.mp3`}),c[216]||=i(),c[217]||=a(`strong`,null,`Monica Geller:`,-1),c[218]||=i(` You like Green Bay?`,-1),c[219]||=a(`blockquote`,null,[a(`p`,null,`你喜欢绿湾吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/056.mp3`}),c[220]||=i(),c[221]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[222]||=i(` Well it’s only like my favorite bay! {Actually, it’s not bad. It just gets a little cold in winter, but in Wisconsin winter only lasts from August to June. J }`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`嗯，它就像我最喜欢的海湾！{事实上，天气还不错。只是冬天有点冷，但在威斯康星州，冬天只从8月持续到6月。J}`)],-1),c[224]||=a(`p`,null,[a(`em`,null,`(Phoebe joins Chandler on the couch as there is a knock on the door which Monica answers.)`)],-1),c[225]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（菲比和钱德勒一起坐在沙发上，这时有人敲门，莫妮卡回答。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/057.mp3`}),c[226]||=i(),c[227]||=a(`strong`,null,`Monica Geller:`,-1),c[228]||=i(` Hey!`,-1),c[229]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/058.mp3`}),c[230]||=i(),c[231]||=a(`strong`,null,`Will:`,-1),c[232]||=i(` Hey!`,-1),c[233]||=a(`blockquote`,null,[a(`p`,null,`嘿！`)],-1),c[234]||=a(`p`,null,[a(`em`,null,`(Oh, I should point out that the live studio audience at this point goes absolutely wild. And I had absolutely no idea that this Will character was that popular! Maybe they should make him the seventh friend. Which would work out just fine since he’s already married to one of them. Will is played by some guy named Brad Pitt, I guess he’s some sort of actor.)`)],-1),c[235]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（哦，我应该指出，现场演播室的观众在这一点上完全疯了。我完全不知道这个威尔的角色会那么受欢迎！也许他们应该让他成为第七个朋友。这会很好，因为他已经和其中一个结了婚。威尔由一个叫布拉德·皮特的人扮演，我想他是某种类型的人（演员的名字。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/059.mp3`}),c[236]||=i(),c[237]||=a(`strong`,null,`Will:`,-1),c[238]||=i(` Happy Thanksgiving!`,-1),c[239]||=a(`blockquote`,null,[a(`p`,null,`感恩节快乐！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/060.mp3`}),c[240]||=i(),c[241]||=a(`strong`,null,`Monica Geller:`,-1),c[242]||=i(` Aww thanks! God Will I’m so glad that you came! You look great! You must’ve lost like…`,-1),c[243]||=a(`blockquote`,null,[a(`p`,null,`哦，谢谢！上帝会的我很高兴你来了！你看起来很棒！你一定输了，就像…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/061.mp3`}),c[244]||=i(),c[245]||=a(`strong`,null,`Will:`,-1),c[246]||=i(` 150 pounds. Yeah, I’m gonna be in one of those Subway sandwich commercials.`,-1),c[247]||=a(`blockquote`,null,[a(`p`,null,`150英镑。是的，我会在地铁三明治的广告里。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/062.mp3`}),c[248]||=i(),c[249]||=a(`strong`,null,`Monica Geller:`,-1),c[250]||=i(` A pie! (Will brought a pie.)`,-1),c[251]||=a(`blockquote`,null,[a(`p`,null,`一个馅饼！（威尔带来了一个馅饼。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/063.mp3`}),c[252]||=i(),c[253]||=a(`strong`,null,`Will:`,-1),c[254]||=i(` Oh right. All right, it’s no fat, it’s no sugar, it’s no dairy…it’s no good. Throw it out.`,-1),c[255]||=a(`blockquote`,null,[a(`p`,null,`哦，对了。好吧，它没有脂肪，它没有糖，它没有奶制品…它不好。扔掉它。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/064.mp3`}),c[256]||=i(),c[257]||=a(`strong`,null,`Monica Geller:`,-1),c[258]||=i(` You wanna meet some people? This is uh; this is my husband Chandler. Chandler, this is Will.`,-1),c[259]||=a(`blockquote`,null,[a(`p`,null,`你想见见一些人吗？这是呃,；这是我丈夫钱德勒。钱德勒，我是威尔。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/065.mp3`}),c[260]||=i(),c[261]||=a(`strong`,null,`Will:`,-1),c[262]||=i(` Hey.`,-1),c[263]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/066.mp3`}),c[264]||=i(),c[265]||=a(`strong`,null,`Chandler Bing:`,-1),c[266]||=i(` Oh hey. I’d shake your hand but uh; I’m really into the game. Plus, I think it’d be better for my ego if we didn’t stand right next to each other.`,-1),c[267]||=a(`blockquote`,null,[a(`p`,null,`哦，嘿。我想和你握手，但是呃；我真的很喜欢这个游戏。另外，我认为如果我们不站在一起，对我的自我更好。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/067.mp3`}),c[268]||=i(),c[269]||=a(`strong`,null,`Monica Geller:`,-1),c[270]||=i(` This is Phoebe.`,-1),c[271]||=a(`blockquote`,null,[a(`p`,null,`我是菲比。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/068.mp3`}),c[272]||=i(),c[273]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[274]||=i(` (nonchalantly glancing) Hey. (Turns back around.) Wow! (Looks up.) Well done.`,-1),c[275]||=a(`blockquote`,null,[a(`p`,null,`（漫不经心地瞥了一眼）嘿。（转身）哇！（抬起头）干得好。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/069.mp3`}),c[276]||=i(),c[277]||=a(`strong`,null,`Monica Geller:`,-1),c[278]||=i(` (to Will) Wanna give me a hand?`,-1),c[279]||=a(`blockquote`,null,[a(`p`,null,`（对威尔）想帮我一下吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/070.mp3`}),c[280]||=i(),c[281]||=a(`strong`,null,`Will:`,-1),c[282]||=i(` Sure! Monica, I can’t get over how great you look! You look stunning!`,-1),c[283]||=a(`blockquote`,null,[a(`p`,null,`当然！莫妮卡，我无法忘记你看起来有多棒！你看起来棒极了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/071.mp3`}),c[284]||=i(),c[285]||=a(`strong`,null,`Monica Geller:`,-1),c[286]||=i(` Well you look incredible too! You’re just—you’re so fit!`,-1),c[287]||=a(`blockquote`,null,[a(`p`,null,`你看起来也很棒！你太健康了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/072.mp3`}),c[288]||=i(),c[289]||=a(`strong`,null,`Chandler Bing:`,-1),c[290]||=i(` I’m watching the game, but I’m not deaf!`,-1),c[291]||=a(`blockquote`,null,[a(`p`,null,`我在看比赛，但我不是聋子！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/073.mp3`}),c[292]||=i(),c[293]||=a(`strong`,null,`Monica Geller:`,-1),c[294]||=i(` Oh umm, I meant to tell you, Ross is coming.`,-1),c[295]||=a(`blockquote`,null,[a(`p`,null,`哦，嗯，我想告诉你，罗斯要来了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/074.mp3`}),c[296]||=i(),c[297]||=a(`strong`,null,`Will:`,-1),c[298]||=i(` Ross is coming. Great! I love Ross!`,-1),c[299]||=a(`blockquote`,null,[a(`p`,null,`罗斯来了。伟大的我爱罗斯！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/075.mp3`}),c[300]||=i(),c[301]||=a(`strong`,null,`Monica Geller:`,-1),c[302]||=i(` Good. And Rachel Green too. (Will stops suddenly.)`,-1),c[303]||=a(`blockquote`,null,[a(`p`,null,`好的。还有瑞秋·格林。（威尔突然停了下来。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/076.mp3`}),c[304]||=i(),c[305]||=a(`strong`,null,`Will:`,-1),c[306]||=i(` Oh.`,-1),c[307]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/077.mp3`}),c[308]||=i(),c[309]||=a(`strong`,null,`Monica Geller:`,-1),c[310]||=i(` Is there a problem?`,-1),c[311]||=a(`blockquote`,null,[a(`p`,null,`有什么问题吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/078.mp3`}),c[312]||=i(),c[313]||=a(`strong`,null,`Will:`,-1),c[314]||=i(` Nope. Uh, it’s okay. It’s just uh, God I hated her.`,-1),c[315]||=a(`blockquote`,null,[a(`p`,null,`没有。嗯，没关系。只是，天啊，我恨她。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/079.mp3`}),c[316]||=i(),c[317]||=a(`strong`,null,`Monica Geller:`,-1),c[318]||=i(` What?`,-1),c[319]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/080.mp3`}),c[320]||=i(),c[321]||=a(`strong`,null,`Will:`,-1),c[322]||=i(` Yeah, I hated her. She was horrible to me in high school. But hey, it was a long time ago, I’m in a good place, it might be actually fun to see her again. You got any cakes or cookies or something? (Starts looking.) No Will no!`,-1),c[323]||=a(`blockquote`,null,[a(`p`,null,`是的，我恨她。她在高中时对我很可怕。但是，嘿，那是很久以前了，我在一个好地方，再次见到她可能会很有趣。你有蛋糕饼干什么的吗？（开始看）不行，不行！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/081.mp3`}),c[324]||=i(),c[325]||=a(`strong`,null,`Chandler Bing:`,-1),c[326]||=i(` (To Phoebe) Y’know, it’s been a while since we’ve screamed something. Maybe we should.`,-1),c[327]||=a(`blockquote`,null,[a(`p`,null,`（对菲比）你知道，我们已经有一段时间没有尖叫了。也许我们应该。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/082.mp3`}),c[328]||=i(),c[329]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[330]||=i(` Oh okay.`,-1),c[331]||=a(`blockquote`,null,[a(`p`,null,`哦，好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/083.mp3`}),c[332]||=i(),c[333]||=a(`strong`,null,`Chandler Bing:`,-1),c[334]||=i(` Oh come on!`,-1),c[335]||=a(`blockquote`,null,[a(`p`,null,`哦，别这样！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/084.mp3`}),c[336]||=i(),c[337]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[338]||=i(` Noooo!! Damn you ref! You burn in hell!!!`,-1),c[339]||=a(`blockquote`,null,[a(`p`,null,`不！！该死的裁判！你在地狱里燃烧！！！`)],-1),c[340]||=a(`p`,null,[a(`em`,null,`(Joey enters eating potato chips.)`)],-1),c[341]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊进来吃薯片。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/085.mp3`}),c[342]||=i(),c[343]||=a(`strong`,null,`Monica Geller:`,-1),c[344]||=i(` Hey, what are you doing? You gotta save room, you’ve got almost an entire turkey to eat.`,-1),c[345]||=a(`blockquote`,null,[a(`p`,null,`嘿，你在干什么？你得留点地方，你几乎有一整只火鸡要吃。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/086.mp3`}),c[346]||=i(),c[347]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[348]||=i(` Let me explain to you how the human body works. I have to warm my stomach first. Eatin’ chips is like stretching.`,-1),c[349]||=a(`blockquote`,null,[a(`p`,null,`让我向你解释一下人体是如何工作的。我得先暖暖胃。吃薯条就像拉伸。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/087.mp3`}),c[350]||=i(),c[351]||=a(`strong`,null,`Monica Geller:`,-1),c[352]||=i(` All right.`,-1),c[353]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/088.mp3`}),c[354]||=i(),c[355]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[356]||=i(` Don’t worry, Tribbianis never get full.`,-1),c[357]||=a(`blockquote`,null,[a(`p`,null,`别担心，特里比安尼斯永远不会吃饱的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/089.mp3`}),c[358]||=i(),c[359]||=a(`strong`,null,`Will:`,-1),c[360]||=i(` I actually know what you’re talking about. I’m here to tell you something my friend, you can eat and eat and eat but nothing will ever fill that void.`,-1),c[361]||=a(`blockquote`,null,[a(`p`,null,`我真的知道你在说什么。我在这里告诉你一件事，我的朋友，你可以吃啊吃啊吃，但是没有什么能填补这个空白。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/090.mp3`}),c[362]||=i(),c[363]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[364]||=i(` (To Monica) Who the hell is this guy?`,-1),c[365]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）这家伙到底是谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/091.mp3`}),c[366]||=i(),c[367]||=a(`strong`,null,`Monica Geller:`,-1),c[368]||=i(` Will! From high school.`,-1),c[369]||=a(`blockquote`,null,[a(`p`,null,`威尔！高中毕业。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/092.mp3`}),c[370]||=i(),c[371]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[372]||=i(` Oh hey!`,-1),c[373]||=a(`blockquote`,null,[a(`p`,null,`哦，嘿！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/093.mp3`}),c[374]||=i(),c[375]||=a(`strong`,null,`Monica Geller:`,-1),c[376]||=i(` (to Will) Joey.`,-1),c[377]||=a(`blockquote`,null,[a(`p`,null,`（对威尔）乔伊。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/094.mp3`}),c[378]||=i(),c[379]||=a(`strong`,null,`Will:`,-1),c[380]||=i(` Hello.`,-1),c[381]||=a(`blockquote`,null,[a(`p`,null,`你好。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/095.mp3`}),c[382]||=i(),c[383]||=a(`strong`,null,`Ross Geller:`,-1),c[384]||=i(` (entering) Will!`,-1),c[385]||=a(`blockquote`,null,[a(`p`,null,`（进来）威尔！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/096.mp3`}),c[386]||=i(),c[387]||=a(`strong`,null,`Will:`,-1),c[388]||=i(` Ross!`,-1),c[389]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/097.mp3`}),c[390]||=i(),c[391]||=a(`strong`,null,`Ross Geller:`,-1),c[392]||=i(` Hey-hey you came! Man you look incredible! Hot stuff! (They hug and Ross realizes what he said.) Hot stuff?`,-1),c[393]||=a(`blockquote`,null,[a(`p`,null,`嘿，嘿，你来了！老兄，你看起来棒极了！性感的人（他们拥抱着，罗斯意识到了他说的话。）热的东西？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/098.mp3`}),c[394]||=i(),c[395]||=a(`strong`,null,`Will:`,-1),c[396]||=i(` It’s good to see you man.`,-1),c[397]||=a(`blockquote`,null,[a(`p`,null,`很高兴见到你，伙计。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/099.mp3`}),c[398]||=i(),c[399]||=a(`strong`,null,`Ross Geller:`,-1),c[400]||=i(` Yeah, you too. Man, so-so what are you up to?`,-1),c[401]||=a(`blockquote`,null,[a(`p`,null,`是的，你也是。伙计，那你在忙什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/100.mp3`}),c[402]||=i(),c[403]||=a(`strong`,null,`Will:`,-1),c[404]||=i(` I’m a commodities broker.`,-1),c[405]||=a(`blockquote`,null,[a(`p`,null,`我是一名商品经纪人。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/101.mp3`}),c[406]||=i(),c[407]||=a(`strong`,null,`Ross Geller:`,-1),c[408]||=i(` Really? Yeah that-that sounds interesting.`,-1),c[409]||=a(`blockquote`,null,[a(`p`,null,`真的吗？是的，听起来很有趣。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/102.mp3`}),c[410]||=i(),c[411]||=a(`strong`,null,`Will:`,-1),c[412]||=i(` Yeah, it’s not. But I’m rich and thin.`,-1),c[413]||=a(`blockquote`,null,[a(`p`,null,`是的，不是。但我又富又瘦。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/103.mp3`}),c[414]||=i(),c[415]||=a(`strong`,null,`Ross Geller:`,-1),c[416]||=i(` Oh! Man I don’t think I’ve seen you since uh, Lance Davis’ graduation party.`,-1),c[417]||=a(`blockquote`,null,[a(`p`,null,`哦！伙计，自从兰斯·戴维斯的毕业派对后我就没见过你。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/104.mp3`}),c[418]||=i(),c[419]||=a(`strong`,null,`Will:`,-1),c[420]||=i(` That was such a fun night!`,-1),c[421]||=a(`blockquote`,null,[a(`p`,null,`那真是一个有趣的夜晚！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/105.mp3`}),c[422]||=i(),c[423]||=a(`strong`,null,`Ross Geller:`,-1),c[424]||=i(` Yeah. It would’ve been good if we had gotten in, but still real fun.`,-1),c[425]||=a(`blockquote`,null,[a(`p`,null,`是的。如果我们能进去就好了，但仍然很有趣。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/106.mp3`}),c[426]||=i(),c[427]||=a(`strong`,null,`Will:`,-1),c[428]||=i(` Yeah.`,-1),c[429]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/107.mp3`}),c[430]||=i(),c[431]||=a(`strong`,null,`Ross Geller:`,-1),c[432]||=i(` Yeah.`,-1),c[433]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/108.mp3`}),c[434]||=i(),c[435]||=a(`strong`,null,`Will:`,-1),c[436]||=i(` God we were lame back then. Do you remember how into dinosaurs we were?`,-1),c[437]||=a(`blockquote`,null,[a(`p`,null,`天哪，那时我们是瘸子。你还记得我们是多么喜欢恐龙吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/109.mp3`}),c[438]||=i(),c[439]||=a(`strong`,null,`Ross Geller:`,-1),c[440]||=i(` (laughs) Yeah.`,-1),c[441]||=a(`blockquote`,null,[a(`p`,null,`（笑）是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/110.mp3`}),c[442]||=i(),c[443]||=a(`strong`,null,`Will:`,-1),c[444]||=i(` So what do you, what do you do now?`,-1),c[445]||=a(`blockquote`,null,[a(`p`,null,`那你现在做什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/111.mp3`}),c[446]||=i(),c[447]||=a(`strong`,null,`Ross Geller:`,-1),c[448]||=i(` So how long are you in town?`,-1),c[449]||=a(`blockquote`,null,[a(`p`,null,`那你在城里呆多久？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/112.mp3`}),c[450]||=i(),c[451]||=a(`strong`,null,`Rachel Green:`,-1),c[452]||=i(` (entering, carrying a baking dish) Hi!`,-1),c[453]||=a(`blockquote`,null,[a(`p`,null,`（拿着烤盘进来）嗨！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/113.mp3`}),c[454]||=i(),c[455]||=a(`strong`,null,`Monica Geller:`,-1),c[456]||=i(` Hey sweetie. Oh good. (Takes the baking dish from her.)`,-1),c[457]||=a(`blockquote`,null,[a(`p`,null,`嘿，亲爱的。哦，很好。（从她手中接过烤盘。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/114.mp3`}),c[458]||=i(),c[459]||=a(`strong`,null,`Will:`,-1),c[460]||=i(` (glaring at Rachel) Rachel Green.`,-1),c[461]||=a(`blockquote`,null,[a(`p`,null,`（怒视着瑞秋）瑞秋·格林。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/115.mp3`}),c[462]||=i(),c[463]||=a(`strong`,null,`Ross Geller:`,-1),c[464]||=i(` Aw—oh, that’s right. Are-are you gonna be okay?`,-1),c[465]||=a(`blockquote`,null,[a(`p`,null,`哦，对了。你没事吧？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/116.mp3`}),c[466]||=i(),c[467]||=a(`strong`,null,`Will:`,-1),c[468]||=i(` Oh, I’ll-I’ll be fine. Just God I hate her Ross! I hate her!`,-1),c[469]||=a(`blockquote`,null,[a(`p`,null,`哦，我会没事的。天哪，我恨她，罗斯！我恨她！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/117.mp3`}),c[470]||=i(),c[471]||=a(`strong`,null,`Ross Geller:`,-1),c[472]||=i(` Will, high school was-was a long time ago.`,-1),c[473]||=a(`blockquote`,null,[a(`p`,null,`威尔，高中是很久以前的事了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/118.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`Will:`,-1),c[476]||=i(` Look at her standing there with those yams! My two greatest enemies **Ross Geller: **Rachel Green and complex carbohydrates.`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,[i(`看看她拿着那些山药站在那里！我最大的两个敌人`),a(`strong`,null,`罗斯·盖勒：`),i(`瑞秋·格林和复合碳水化合物。`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/119.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`Rachel Green:`,-1),c[480]||=i(` (sees Will) Oh my God Monica, who is that?`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`（看到威尔）哦，我的天，莫妮卡，那是谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/120.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`Monica Geller:`,-1),c[484]||=i(` That’s Will from high school!`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`那是高中的威尔！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/121.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`Rachel Green:`,-1),c[488]||=i(` Oh! I do not remember him! Wow! He's really got that sexy, smoldering thing going on. (We see Will angrily staring at Rachel.) Oh my God, he’s… Look at the way he’s just staring at me. I think he’s trying to mouth something to me, but I can’t make it out. (Will mouths, "I hate you.")`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`哦！我不记得他了！哇！他真的很性感，很性感。（我们看到威尔愤怒地盯着瑞秋。）哦，天哪，他……看看他盯着我的样子。我想他想对我说点什么，但我看不出来。（威尔说，“我恨你。”）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/122.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`Monica Geller:`,-1),c[492]||=i(` Okay, dinner’s ready!`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`好了，晚餐准备好了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/123.mp3`}),c[494]||=i(),c[495]||=a(`strong`,null,`Chandler Bing:`,-1),c[496]||=i(` Good game!`,-1),c[497]||=a(`blockquote`,null,[a(`p`,null,`打得好！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/124.mp3`}),c[498]||=i(),c[499]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[500]||=i(` Yeah.`,-1),c[501]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/125.mp3`}),c[502]||=i(),c[503]||=a(`strong`,null,`Chandler Bing:`,-1),c[504]||=i(` Yeah. Solid effort. Solid effort.`,-1),c[505]||=a(`blockquote`,null,[a(`p`,null,`是的。扎实的努力。扎实的努力。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/126.mp3`}),c[506]||=i(),c[507]||=a(`strong`,null,`Monica Geller:`,-1),c[508]||=i(` Oh, so who won?`,-1),c[509]||=a(`blockquote`,null,[a(`p`,null,`哦，那谁赢了？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/127.mp3`}),c[510]||=i(),c[511]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[512]||=i(` (simultaneously) Green Bay.`,-1),c[513]||=a(`blockquote`,null,[a(`p`,null,`（同时）绿湾。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/128.mp3`}),c[514]||=i(),c[515]||=a(`strong`,null,`Chandler Bing:`,-1),c[516]||=i(` (simultaneously) Detroit.`,-1),c[517]||=a(`blockquote`,null,[a(`p`,null,`（同时）底特律。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/129.mp3`}),c[518]||=i(),c[519]||=a(`strong`,null,`Monica Geller:`,-1),c[520]||=i(` What?`,-1),c[521]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/130.mp3`}),c[522]||=i(),c[523]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[524]||=i(` Well the Lions technically won, but it was a moral victory for the Green Bay…Mermen.`,-1),c[525]||=a(`blockquote`,null,[a(`p`,null,`从技术上说，狮子队赢了，但对绿湾来说，这是一场道义上的胜利……美人鱼。`)],-1),c[526]||=a(`p`,null,[a(`em`,null,`(They sit down at the table and Will goes to talk to Rachel.)`)],-1),c[527]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（他们坐在桌旁，威尔去和瑞秋说话。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/131.mp3`}),c[528]||=i(),c[529]||=a(`strong`,null,`Rachel Green:`,-1),c[530]||=i(` Hi! Will, right?`,-1),c[531]||=a(`blockquote`,null,[a(`p`,null,`嗨！威尔，对吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/132.mp3`}),c[532]||=i(),c[533]||=a(`strong`,null,`Will:`,-1),c[534]||=i(` Right.`,-1),c[535]||=a(`blockquote`,null,[a(`p`,null,`对。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/133.mp3`}),c[536]||=i(),c[537]||=a(`strong`,null,`Rachel Green:`,-1),c[538]||=i(` Hi! I’m Rachel Green.`,-1),c[539]||=a(`blockquote`,null,[a(`p`,null,`嗨！我是瑞秋·格林。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/134.mp3`}),c[540]||=i(),c[541]||=a(`strong`,null,`Will:`,-1),c[542]||=i(` Oh I-I remember you.`,-1),c[543]||=a(`blockquote`,null,[a(`p`,null,`哦，我记得你。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/135.mp3`}),c[544]||=i(),c[545]||=a(`strong`,null,`Rachel Green:`,-1),c[546]||=i(` Really?! Aren’t you sweet! I gotta tell you though, I am, I am having the hardest time placing you. Oh-oh hang on! Did we umm, did we fool around at Lance Davis’ graduation party?`,-1),c[547]||=a(`blockquote`,null,[a(`p`,null,`真的吗？！你真可爱！我得告诉你，我是，我最难安置你。哦，等等！我们有没有在兰斯·戴维斯的毕业派对上鬼混？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/136.mp3`}),c[548]||=i(),c[549]||=a(`strong`,null,`Will:`,-1),c[550]||=i(` You are unbelievable.`,-1),c[551]||=a(`blockquote`,null,[a(`p`,null,`你真是难以置信。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/137.mp3`}),c[552]||=i(),c[553]||=a(`strong`,null,`Rachel Green:`,-1),c[554]||=i(` Thank you!`,-1),c[555]||=a(`blockquote`,null,[a(`p`,null,`谢谢你！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/138.mp3`}),c[556]||=i(),c[557]||=a(`strong`,null,`Monica Geller:`,-1),c[558]||=i(` (breaking it up) Uh Rachel? Rachel, why don’t you sit here? (Next to Joey) And Will you sit way over there. (The other side of the table.)`,-1),c[559]||=a(`blockquote`,null,[a(`p`,null,`（分手）呃，瑞秋？瑞秋，你为什么不坐在这儿？（乔伊旁边）你坐那边好吗。（桌子的另一边。）`)],-1),c[560]||=a(`p`,null,[a(`em`,null,`(Monica sets something on the table and removes the cover. It kinda looks like turkey.)`)],-1),c[561]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（莫妮卡在桌上放了些东西，然后取下盖子。它看起来有点像火鸡。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/139.mp3`}),c[562]||=i(),c[563]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[564]||=i(` That’s it?! Even if nobody helps me I can eat that no problem. At least give me a challenge!`,-1),c[565]||=a(`blockquote`,null,[a(`p`,null,`就这样？！即使没人帮我，我也能吃，没问题。至少给我一个挑战！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/140.mp3`}),c[566]||=i(),c[567]||=a(`strong`,null,`Monica Geller:`,-1),c[568]||=i(` (laughs) This is Chandler’s chicken. This is the turkey. (Sets down a huge turkey.)`,-1),c[569]||=a(`blockquote`,null,[a(`p`,null,`（笑）这是钱德勒的鸡。这是火鸡。（放下一只巨大的火鸡。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/141.mp3`}),c[570]||=i(),c[571]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[572]||=i(` (quietly) Oh. How-how big is that?`,-1),c[573]||=a(`blockquote`,null,[a(`p`,null,`（平静地）哦。那有多大？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/142.mp3`}),c[574]||=i(),c[575]||=a(`strong`,null,`Monica Geller:`,-1),c[576]||=i(` About nineteen pounds.`,-1),c[577]||=a(`blockquote`,null,[a(`p`,null,`大约十九磅。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/143.mp3`}),c[578]||=i(),c[579]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[580]||=i(` (To Rachel) It’s like me when I was born.`,-1),c[581]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）就像我出生时一样。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/144.mp3`}),c[582]||=i(),c[583]||=a(`strong`,null,`Rachel Green:`,-1),c[584]||=i(` All right, who would uh, like some yams? Will?`,-1),c[585]||=a(`blockquote`,null,[a(`p`,null,`好吧，谁会，呃，想要些山药？会吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/145.mp3`}),c[586]||=i(),c[587]||=a(`strong`,null,`Will:`,-1),c[588]||=i(` Oh, you’d like that wouldn’t ya?`,-1),c[589]||=a(`blockquote`,null,[a(`p`,null,`哦，你会喜欢的，是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/146.mp3`}),c[590]||=i(),c[591]||=a(`strong`,null,`Rachel Green:`,-1),c[592]||=i(` What? (Joey starts offering Ross some turkey.) Oh y’know what? Can we please keep the chicken and the turkey and everything on the other side of the table? The smell is just yuck!`,-1),c[593]||=a(`blockquote`,null,[a(`p`,null,`什么？（乔伊开始给罗斯一些火鸡）哦，你知道吗？我们能把鸡肉、火鸡和其他东西放在桌子的另一边吗？这气味真难闻！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/147.mp3`}),c[594]||=i(),c[595]||=a(`strong`,null,`Will:`,-1),c[596]||=i(` (sneeze talks) Typical.`,-1),c[597]||=a(`blockquote`,null,[a(`p`,null,`（打喷嚏）很典型。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/148.mp3`}),c[598]||=i(),c[599]||=a(`strong`,null,`Rachel Green:`,-1),c[600]||=i(` I’m sorry. What?`,-1),c[601]||=a(`blockquote`,null,[a(`p`,null,`对不起。什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/149.mp3`}),c[602]||=i(),c[603]||=a(`strong`,null,`Will:`,-1),c[604]||=i(` I said it was typical. Typical of you, Rachel Green, Queen Rachel does whatever she wants in little Rachel land. (Does a fake hair flip.)`,-1),c[605]||=a(`blockquote`,null,[a(`p`,null,`我说这是典型的。瑞秋·格林，瑞秋女王是你的典型，她在小瑞秋土地上想干什么就干什么。（假发会翻转。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/150.mp3`}),c[606]||=i(),c[607]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[608]||=i(` (To Monica) Seriously, who is this guy?`,-1),c[609]||=a(`blockquote`,null,[a(`p`,null,`（对莫妮卡）说真的，这家伙是谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/151.mp3`}),c[610]||=i(),c[611]||=a(`strong`,null,`Rachel Green:`,-1),c[612]||=i(` Umm, I’m sorry. Do you-do you have a problem with me?`,-1),c[613]||=a(`blockquote`,null,[a(`p`,null,`嗯，对不起。你对我有意见吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/152.mp3`}),c[614]||=i(),c[615]||=a(`strong`,null,`Will:`,-1),c[616]||=i(` I don’t know? Do I? Do I?`,-1),c[617]||=a(`blockquote`,null,[a(`p`,null,`我不知道？是吗？是吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/153.mp3`}),c[618]||=i(),c[619]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[620]||=i(` I think you do.`,-1),c[621]||=a(`blockquote`,null,[a(`p`,null,`我想是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/154.mp3`}),c[622]||=i(),c[623]||=a(`strong`,null,`Monica Geller:`,-1),c[624]||=i(` (To Rachel) Apparently you were umm, a little mean to him in high school.`,-1),c[625]||=a(`blockquote`,null,[a(`p`,null,`（对瑞秋）显然你在高中时对他有点刻薄。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/155.mp3`}),c[626]||=i(),c[627]||=a(`strong`,null,`Will:`,-1),c[628]||=i(` A little mean? You made my life miserable!`,-1),c[629]||=a(`blockquote`,null,[a(`p`,null,`有点小气？你让我的生活很悲惨！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/156.mp3`}),c[630]||=i(),c[631]||=a(`strong`,null,`Rachel Green:`,-1),c[632]||=i(` I’m-I’m—I had no idea. I’m sorry. I…`,-1),c[633]||=a(`blockquote`,null,[a(`p`,null,`我不知道。我很抱歉。我…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/157.mp3`}),c[634]||=i(),c[635]||=a(`strong`,null,`Will:`,-1),c[636]||=i(` Well you should be. Screw it! Bring on the yams!`,-1),c[637]||=a(`blockquote`,null,[a(`p`,null,`你应该是。去他妈的！把山药拿来！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/158.mp3`}),c[638]||=i(),c[639]||=a(`strong`,null,`Monica Geller:`,-1),c[640]||=i(` Oh Will. But you-you’ve worked so hard…`,-1),c[641]||=a(`blockquote`,null,[a(`p`,null,`哦，我会的。但是你工作这么努力…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/159.mp3`}),c[642]||=i(),c[643]||=a(`strong`,null,`Will:`,-1),c[644]||=i(` Yams!!!!`,-1),c[645]||=a(`blockquote`,null,[a(`p`,null,`山药！！！！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/160.mp3`}),c[646]||=i(),c[647]||=a(`strong`,null,`Monica Geller:`,-1),c[648]||=i(` Okay. (Chandler grabs the dish from Monica and hands it to Will who starts dishing out a large helping.)`,-1),c[649]||=a(`blockquote`,null,[a(`p`,null,`好的。（钱德勒从莫妮卡手中接过盘子，递给威尔，威尔开始端出一大盘。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/161.mp3`}),c[650]||=i(),c[651]||=a(`strong`,null,`Rachel Green:`,-1),c[652]||=i(` Uh Will umm, I just want to say that I’m real sorry for whatever I-I did to you in high school…`,-1),c[653]||=a(`blockquote`,null,[a(`p`,null,`嗯，威尔，我只是想说，我真的很抱歉我高中时对你所做的一切…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/162.mp3`}),c[654]||=i(),c[655]||=a(`strong`,null,`Will:`,-1),c[656]||=i(` Oh, it wasn’t just me. We had a club!`,-1),c[657]||=a(`blockquote`,null,[a(`p`,null,`哦，不仅仅是我。我们有一个俱乐部！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/163.mp3`}),c[658]||=i(),c[659]||=a(`strong`,null,`Rachel Green:`,-1),c[660]||=i(` You had a club?!`,-1),c[661]||=a(`blockquote`,null,[a(`p`,null,`你有俱乐部？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/164.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`Will:`,-1),c[664]||=i(` That’s right, The I Hate Rachel Green Club!`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`没错，我讨厌瑞秋绿色俱乐部！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/165.mp3`}),c[666]||=i(),c[667]||=a(`strong`,null,`Rachel Green:`,-1),c[668]||=i(` Whoa! My God! So what, you all just joined together to hate me?! Who else was in this club?`,-1),c[669]||=a(`blockquote`,null,[a(`p`,null,`哇！天哪！那又怎样，你们只是为了恨我而联合起来？！俱乐部里还有谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/166.mp3`}),c[670]||=i(),c[671]||=a(`strong`,null,`Will:`,-1),c[672]||=i(` Me and Ross. (Points at Ross.)`,-1),c[673]||=a(`blockquote`,null,[a(`p`,null,`我和罗斯。（指着罗斯。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/167.mp3`}),c[674]||=t(` <strong>Ross Geller:</strong> No need to point, she knows who Ross is.<blockquote><p>不用说，她知道罗斯是谁。</p></blockquote><p>Commercial Break</p><blockquote><p>商业休息</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, scene continued from earlier.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒家，场景从早些时候开始继续。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E09/168.mp3`}),c[675]||=i(),c[676]||=a(`strong`,null,`Rachel Green:`,-1),c[677]||=i(` (To Ross) So you were in an I Hate Rachel club?`,-1),c[678]||=a(`blockquote`,null,[a(`p`,null,`（对罗斯）那么你参加了我恨瑞秋俱乐部？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/169.mp3`}),c[679]||=i(),c[680]||=a(`strong`,null,`Will:`,-1),c[681]||=i(` Yes he was. (Holds up his hand for a high-five.)`,-1),c[682]||=a(`blockquote`,null,[a(`p`,null,`是的。（举起手来击掌。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/170.mp3`}),c[683]||=i(),c[684]||=a(`strong`,null,`Ross Geller:`,-1),c[685]||=i(` No. No.`,-1),c[686]||=a(`blockquote`,null,[a(`p`,null,`不，不。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/171.mp3`}),c[687]||=i(),c[688]||=a(`strong`,null,`Rachel Green:`,-1),c[689]||=i(` So who else was in this club?`,-1),c[690]||=a(`blockquote`,null,[a(`p`,null,`那么俱乐部里还有谁？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/172.mp3`}),c[691]||=i(),c[692]||=a(`strong`,null,`Ross Geller:`,-1),c[693]||=i(` Uh actually, there-there was also that exchange student from Thailand but I-I don’t think he-he knew what it was.`,-1),c[694]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，还有一个来自泰国的交换生，但我想他不知道那是什么。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/173.mp3`}),c[695]||=i(),c[696]||=a(`strong`,null,`Rachel Green:`,-1),c[697]||=i(` So Ross, we went out for two years, and you never told me you were in an I Hate Rachel club.`,-1),c[698]||=a(`blockquote`,null,[a(`p`,null,`罗斯，我们约会了两年，你从没告诉我你在一个我讨厌瑞秋的俱乐部。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/174.mp3`}),c[699]||=i(),c[700]||=a(`strong`,null,`Will:`,-1),c[701]||=i(` You went out with her?! We had a pact!`,-1),c[702]||=a(`blockquote`,null,[a(`p`,null,`你和她出去了？！我们有个约定！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/175.mp3`}),c[703]||=i(),c[704]||=a(`strong`,null,`Ross Geller:`,-1),c[705]||=i(` That was in high school! It’s not like it was binding forever.`,-1),c[706]||=a(`blockquote`,null,[a(`p`,null,`那是在高中！它不像是永远的束缚。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/176.mp3`}),c[707]||=i(),c[708]||=a(`strong`,null,`Will:`,-1),c[709]||=i(` Then why did it have the word eternity in it?`,-1),c[710]||=a(`blockquote`,null,[a(`p`,null,`那为什么里面有永恒这个词呢？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/177.mp3`}),c[711]||=i(),c[712]||=a(`strong`,null,`Rachel Green:`,-1),c[713]||=i(` Okay Monica, did you know about this?!`,-1),c[714]||=a(`blockquote`,null,[a(`p`,null,`好吧，莫妮卡，你知道这件事吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/178.mp3`}),c[715]||=i(),c[716]||=a(`strong`,null,`Monica Geller:`,-1),c[717]||=i(` I swear I didn’t. (To Ross and Will) Hey! Is that why you guys used to go up to your bedroom and lock the door?`,-1),c[718]||=a(`blockquote`,null,[a(`p`,null,`我发誓我没有。（对罗斯和威尔）嘿！这就是为什么你们经常去卧室锁门？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/179.mp3`}),c[719]||=i(),c[720]||=a(`strong`,null,`Ross and Will:`,-1),c[721]||=i(` Yeah.`,-1),c[722]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/180.mp3`}),c[723]||=i(),c[724]||=a(`strong`,null,`Monica Geller:`,-1),c[725]||=i(` Hmm, a little relieved, I gotta say.`,-1),c[726]||=a(`blockquote`,null,[a(`p`,null,`嗯，我得说，我松了一口气。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/181.mp3`}),c[727]||=i(),c[728]||=a(`strong`,null,`Ross Geller:`,-1),c[729]||=i(` Look Rach I-I’m sorry, okay? I…I was a stupid kid, okay? The only reason I joined…`,-1),c[730]||=a(`blockquote`,null,[a(`p`,null,`听着，瑞秋，对不起，好吗？我…我是个愚蠢的孩子，好吗？我加入的唯一原因…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/182.mp3`}),c[731]||=i(),c[732]||=a(`strong`,null,`Will:`,-1),c[733]||=i(` Co-founded!`,-1),c[734]||=a(`blockquote`,null,[a(`p`,null,`共同创立！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/183.mp3`}),c[735]||=i(),c[736]||=a(`strong`,null,`Ross Geller:`,-1),c[737]||=i(` …co-founded. Co-founded the club was because I was insanely in love with you. Obviously I didn’t handle it very well. But if you think about it the I Hate Rachel Club was really the I Love Rachel Club.`,-1),c[738]||=a(`blockquote`,null,[a(`p`,null,`……共同创立的。共同创建这个俱乐部是因为我疯狂地爱上了你。显然我处理得不太好。但如果你想一想，我恨瑞秋俱乐部是真正的我爱瑞秋俱乐部。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/184.mp3`}),c[739]||=i(),c[740]||=a(`strong`,null,`Will:`,-1),c[741]||=i(` Uh, except that it was really the I Hate Rachel Club.`,-1),c[742]||=a(`blockquote`,null,[a(`p`,null,`嗯，除了我讨厌瑞秋俱乐部。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/185.mp3`}),c[743]||=i(),c[744]||=a(`strong`,null,`Rachel Green:`,-1),c[745]||=i(` Okay. So what? You guys would just like get together and like just say mean things about me?`,-1),c[746]||=a(`blockquote`,null,[a(`p`,null,`好的。那又怎么样？你们想聚在一起说我的坏话吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/186.mp3`}),c[747]||=i(),c[748]||=a(`strong`,null,`Will:`,-1),c[749]||=i(` Well, we did a little more than that.`,-1),c[750]||=a(`blockquote`,null,[a(`p`,null,`嗯，我们做的还不止这些。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/187.mp3`}),c[751]||=i(),c[752]||=a(`strong`,null,`Ross Geller:`,-1),c[753]||=i(` No-no! No-no. No-no.`,-1),c[754]||=a(`blockquote`,null,[a(`p`,null,`不，不！不，不，不。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/188.mp3`}),c[755]||=i(),c[756]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[757]||=i(` What?! What else did you do?`,-1),c[758]||=a(`blockquote`,null,[a(`p`,null,`什么？！你还做了什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/189.mp3`}),c[759]||=i(),c[760]||=a(`strong`,null,`Will:`,-1),c[761]||=i(` We started a rumor.`,-1),c[762]||=a(`blockquote`,null,[a(`p`,null,`我们开始散布谣言。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/190.mp3`}),c[763]||=i(),c[764]||=a(`strong`,null,`Rachel Green:`,-1),c[765]||=i(` What rumor?`,-1),c[766]||=a(`blockquote`,null,[a(`p`,null,`什么谣言？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/191.mp3`}),c[767]||=i(),c[768]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[769]||=i(` Oh, come on Will! Just take off your shirt and tell us!`,-1),c[770]||=a(`blockquote`,null,[a(`p`,null,`哦，来吧，威尔！脱下你的衬衫告诉我们！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/192.mp3`}),c[771]||=i(),c[772]||=a(`strong`,null,`Rachel Green:`,-1),c[773]||=i(` Ross!`,-1),c[774]||=a(`blockquote`,null,[a(`p`,null,`罗斯！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/193.mp3`}),c[775]||=i(),c[776]||=a(`strong`,null,`Ross Geller:`,-1),c[777]||=i(` It was no big deal. We-we…said that the rumor was…that umm…you had both…male and female reproductive parts.`,-1),c[778]||=a(`blockquote`,null,[a(`p`,null,`没什么大不了的。我们…我们…说谣言是…嗯…你同时有…雄性和雌性生殖器官。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/194.mp3`}),c[779]||=i(),c[780]||=a(`strong`,null,`Rachel Green:`,-1),c[781]||=i(` What?!`,-1),c[782]||=a(`blockquote`,null,[a(`p`,null,`什么？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/195.mp3`}),c[783]||=i(),c[784]||=a(`strong`,null,`Will:`,-1),c[785]||=i(` That’s right! We said your parents flipped a coin, decided to raise you as a girl, but you still had a hint of a penis.`,-1),c[786]||=a(`blockquote`,null,[a(`p`,null,`没错！我们说你父母掷硬币决定把你培养成女孩，但你仍然有阴茎的迹象。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/196.mp3`}),c[787]||=i(),c[788]||=a(`strong`,null,`Rachel Green:`,-1),c[789]||=i(` (shocked) Oh my God!`,-1),c[790]||=a(`blockquote`,null,[a(`p`,null,`（震惊）哦，我的天啊！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/197.mp3`}),c[791]||=i(),c[792]||=a(`strong`,null,`Monica Geller:`,-1),c[793]||=i(` You started that?!`,-1),c[794]||=a(`blockquote`,null,[a(`p`,null,`是你开始的？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/198.mp3`}),c[795]||=i(),c[796]||=a(`strong`,null,`Rachel Green:`,-1),c[797]||=i(` What?! You heard that?! (Goes and stands behind Joey.)`,-1),c[798]||=a(`blockquote`,null,[a(`p`,null,`什么？！你听到了吗？！（走到乔伊身后。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/199.mp3`}),c[799]||=i(),c[800]||=a(`strong`,null,`Monica Geller:`,-1),c[801]||=i(` Everyone at our school heard it!`,-1),c[802]||=a(`blockquote`,null,[a(`p`,null,`我们学校的每个人都听到了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/200.mp3`}),c[803]||=i(),c[804]||=a(`strong`,null,`Chandler Bing:`,-1),c[805]||=i(` Everybody at my school heard it! You were the hermaphrodite cheerleader from Long Island?!`,-1),c[806]||=a(`blockquote`,null,[a(`p`,null,`我学校的每个人都听到了！你是来自长岛的雌雄同体啦啦队长？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/201.mp3`}),c[807]||=i(),c[808]||=a(`strong`,null,`Rachel Green:`,-1),c[809]||=i(` Oh no!!!! Oh my God!! This is all making so much sense to me now! This is why Adam Carter wouldn’t go out with me! This is why Billy Tratt would just stay in this region! (Motions to her breasts.) (Joey has turned around.)`,-1),c[810]||=a(`blockquote`,null,[a(`p`,null,`哦，不！！！！哦，我的上帝！！这一切现在对我来说太有意义了！这就是为什么亚当·卡特不跟我出去！这就是为什么比利·塔特会留在这个地区！（对着她的乳房做手势。）（乔伊转过身来。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/202.mp3`}),c[811]||=i(),c[812]||=a(`strong`,null,`Ross Geller:`,-1),c[813]||=i(` Actually, Billy Tratt is gay now. So-so that one’s not really our fault.`,-1),c[814]||=a(`blockquote`,null,[a(`p`,null,`事实上，比利·塔特现在是同性恋了。所以这不是我们的错。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/203.mp3`}),c[815]||=i(),c[816]||=a(`strong`,null,`Rachel Green:`,-1),c[817]||=i(` Monica, how come you never told me this?!`,-1),c[818]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡，你怎么从来没告诉我这些？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/204.mp3`}),c[819]||=i(),c[820]||=a(`strong`,null,`Monica Geller:`,-1),c[821]||=i(` I thought it might be true. And I was afraid that you were gonna cry and then show it to me.`,-1),c[822]||=a(`blockquote`,null,[a(`p`,null,`我想这可能是真的。我担心你会哭然后把它给我看。`)],-1),c[823]||=a(`p`,null,[a(`em`,null,`(Joey is now looking at Rachel, and since Rachel’s standing and he’s sitting down and he’s not looking at her face… You get the picture.)`)],-1),c[824]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊现在看着瑞秋，瑞秋站着，他坐着，他没有看着她的脸……你明白了。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/205.mp3`}),c[825]||=i(),c[826]||=a(`strong`,null,`Rachel Green:`,-1),c[827]||=i(` Joey stop staring! There’s nothing there! It’s not true!`,-1),c[828]||=a(`blockquote`,null,[a(`p`,null,`乔伊，别盯着看了！那里什么都没有！这不是真的！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/206.mp3`}),c[829]||=i(),c[830]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[831]||=i(` I’m afraid I’m gonna need proof.`,-1),c[832]||=a(`blockquote`,null,[a(`p`,null,`恐怕我需要证据。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/207.mp3`}),c[833]||=i(),c[834]||=a(`strong`,null,`Rachel Green:`,-1),c[835]||=i(` Oh! (Hits him and storms out.)`,-1),c[836]||=a(`blockquote`,null,[a(`p`,null,`哦！（打了他一下，冲出去。）`)],-1),c[837]||=a(`p`,null,[i(`⏱ `),a(`em`,null,`Time Lapse, dinner has ended for everyone except Joey who looks like to have finished the turkey, until he turns the plate around and reveals he only ate one side.`)],-1),c[838]||=a(`blockquote`,null,[a(`p`,null,[i(`⏱ `),a(`em`,null,`随着时间的推移，所有人的晚餐都结束了，除了看起来已经吃完火鸡的乔伊，直到他把盘子转过来，露出只吃了一面。`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/208.mp3`}),c[839]||=i(),c[840]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[841]||=i(` You are my Everest.`,-1),c[842]||=a(`blockquote`,null,[a(`p`,null,`你是我的珠穆朗玛峰。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/209.mp3`}),c[843]||=i(),c[844]||=a(`strong`,null,`Monica Geller:`,-1),c[845]||=i(` Joey, you don’t have to finish that.`,-1),c[846]||=a(`blockquote`,null,[a(`p`,null,`乔伊，你不必完成。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/210.mp3`}),c[847]||=i(),c[848]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[849]||=i(` Oh yes I do. Otherwise what’s next? Today I’m just a guy who can’t finish a turkey, but tomorrow I’m the guy who eats half a Powerbar, wraps up the rest, and puts in the fridge? No! No, I just…I just—I gotta change my pants. (Gets up and heads for the door.) Jeans have no give. (Exits.)`,-1),c[850]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，我喜欢。否则下一步怎么办？今天我只是一个吃不完火鸡的人，但明天我就是那个吃半块能量棒，把剩下的打包，然后放进冰箱的人？不不，我只是…我只是…我要换裤子。（站起来，朝门口走去。）牛仔裤没有退路。（退出。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/211.mp3`}),c[851]||=i(),c[852]||=a(`strong`,null,`Rachel Green:`,-1),c[853]||=i(` (entering carrying a book) Okay! Okay! Listen to what Sean McMahon wrote in my yearbook senior year, "Dear Rach, you’re such a good person." Not girl! Person!`,-1),c[854]||=a(`blockquote`,null,[a(`p`,null,`（拿着一本书进来）好的！可以听听肖恩·麦克马洪在我的高中年鉴上写的，“亲爱的瑞秋，你真是个好人。”不是女孩！人！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/212.mp3`}),c[855]||=i(),c[856]||=a(`strong`,null,`Ross Geller:`,-1),c[857]||=i(` Rach, I think you’re reading a little too much into it.`,-1),c[858]||=a(`blockquote`,null,[a(`p`,null,`瑞秋，我觉得你读得太多了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/213.mp3`}),c[859]||=i(),c[860]||=a(`strong`,null,`Rachel Green:`,-1),c[861]||=i(` (reading what he wrote again) "Dear Rach, you’re a great person. Sorry about your tiney-wienie." (Will laughs.)`,-1),c[862]||=a(`blockquote`,null,[a(`p`,null,`（又读了一遍他写的话）“亲爱的瑞秋，你是一个伟大的人。为你的蒂尼·维尼感到抱歉。”（威尔笑了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/214.mp3`}),c[863]||=i(),c[864]||=a(`strong`,null,`Ross Geller:`,-1),c[865]||=i(` Look, what do you want me to do? Do you want me to call everyone in the entire school and tell them it wasn’t true?!`,-1),c[866]||=a(`blockquote`,null,[a(`p`,null,`听着，你想让我做什么？你想让我给全校所有人打电话告诉他们这不是真的吗？！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/215.mp3`}),c[867]||=i(),c[868]||=a(`strong`,null,`Rachel Green:`,-1),c[869]||=i(` Yes!`,-1),c[870]||=a(`blockquote`,null,[a(`p`,null,`是的！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/216.mp3`}),c[871]||=i(),c[872]||=a(`strong`,null,`Will:`,-1),c[873]||=i(` Could you also tell them I’m skinny now?`,-1),c[874]||=a(`blockquote`,null,[a(`p`,null,`你能告诉他们我现在很瘦吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/217.mp3`}),c[875]||=i(),c[876]||=a(`strong`,null,`Monica Geller:`,-1),c[877]||=i(` Oh! Me too!`,-1),c[878]||=a(`blockquote`,null,[a(`p`,null,`哦！我也是！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/218.mp3`}),c[879]||=i(),c[880]||=a(`strong`,null,`Ross Geller:`,-1),c[881]||=i(` Well look-look I’m not calling anybody! Okay? It was like a million years ago!`,-1),c[882]||=a(`blockquote`,null,[a(`p`,null,`听着，我没给任何人打电话！可以那是一百万年前的事了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/219.mp3`}),c[883]||=i(),c[884]||=a(`strong`,null,`Rachel Green:`,-1),c[885]||=i(` I don’t care how long ago it was! You told people that I was half and half! Y’know what? I just want to point out I never did anything to hurt you in high school.`,-1),c[886]||=a(`blockquote`,null,[a(`p`,null,`我不在乎那是多久以前的事了！你告诉人们我是一半一半！你知道吗？我只想指出我高中时从没做过伤害你的事。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/220.mp3`}),c[887]||=i(),c[888]||=a(`strong`,null,`Monica Geller:`,-1),c[889]||=i(` That’s not totally true.`,-1),c[890]||=a(`blockquote`,null,[a(`p`,null,`那不完全是真的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/221.mp3`}),c[891]||=i(),c[892]||=a(`strong`,null,`Rachel Green:`,-1),c[893]||=i(` What?`,-1),c[894]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/222.mp3`}),c[895]||=i(),c[896]||=a(`strong`,null,`Ross Geller:`,-1),c[897]||=i(` What?`,-1),c[898]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/223.mp3`}),c[899]||=i(),c[900]||=a(`strong`,null,`Monica Geller:`,-1),c[901]||=i(` Well you-you did start that rumor about Ross making out with Mrs. Altman, our 50-year-old librarian.`,-1),c[902]||=a(`blockquote`,null,[a(`p`,null,`是你开始散布谣言说罗斯和我们50岁的图书管理员奥特曼夫人亲热了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/224.mp3`}),c[903]||=i(),c[904]||=a(`strong`,null,`Ross Geller:`,-1),c[905]||=i(` (shocked) (To Rachel) How did you know that?!!!!`,-1),c[906]||=a(`blockquote`,null,[a(`p`,null,`（震惊）（对瑞秋）你怎么知道的？！！！！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/225.mp3`}),c[907]||=i(),c[908]||=a(`strong`,null,`Monica Geller:`,-1),c[909]||=i(` It’s true?!!`,-1),c[910]||=a(`blockquote`,null,[a(`p`,null,`是真的？！！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/226.mp3`}),c[911]||=i(),c[912]||=a(`strong`,null,`Ross Geller:`,-1),c[913]||=i(` No.`,-1),c[914]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/227.mp3`}),c[915]||=i(),c[916]||=a(`strong`,null,`Rachel Green:`,-1),c[917]||=i(` Yes it is! I saw you guys going at it behind the card catalog!`,-1),c[918]||=a(`blockquote`,null,[a(`p`,null,`是的！我看见你们在卡片目录后面干！`)],-1),c[919]||=a(`p`,null,[a(`em`,null,`(Ross is at a loss for words.)`)],-1),c[920]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（罗斯不知所措。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/228.mp3`}),c[921]||=i(),c[922]||=a(`strong`,null,`Will:`,-1),c[923]||=i(` Mrs. Altman? She also made out with Takaka Ci-Kek the night before he went back to Thailand.`,-1),c[924]||=a(`blockquote`,null,[a(`p`,null,`奥特曼夫人？在Takaka Ci Kek返回泰国的前一天晚上，她还与他亲热。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/229.mp3`}),c[925]||=i(),c[926]||=a(`strong`,null,`Chandler Bing:`,-1),c[927]||=i(` I’m sorry. When you were in high school you made out with a 50-year-old woman?`,-1),c[928]||=a(`blockquote`,null,[a(`p`,null,`对不起。你高中时和一个50岁的女人亲热？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/230.mp3`}),c[929]||=i(),c[930]||=a(`strong`,null,`Ross Geller:`,-1),c[931]||=i(` Hey! She didn’t look 50!`,-1),c[932]||=a(`blockquote`,null,[a(`p`,null,`嘿！她看起来不像50岁！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/231.mp3`}),c[933]||=i(),c[934]||=a(`strong`,null,`Chandler Bing:`,-1),c[935]||=i(` Did she look 16?`,-1),c[936]||=a(`blockquote`,null,[a(`p`,null,`她看起来16岁吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/232.mp3`}),c[937]||=i(),c[938]||=a(`strong`,null,`Rachel Green:`,-1),c[939]||=i(` Ohh, there’s a picture of her in the yearbook actually.`,-1),c[940]||=a(`blockquote`,null,[a(`p`,null,`哦，年鉴上有她的照片。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/233.mp3`}),c[941]||=i(),c[942]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[943]||=i(` Oh! (They all look.) Wow!`,-1),c[944]||=a(`blockquote`,null,[a(`p`,null,`哦！（他们都看起来）哇！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/234.mp3`}),c[945]||=i(),c[946]||=a(`strong`,null,`Ross Geller:`,-1),c[947]||=i(` She didn’t photograph well!`,-1),c[948]||=a(`blockquote`,null,[a(`p`,null,`她拍得不好！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/235.mp3`}),c[949]||=i(),c[950]||=a(`strong`,null,`Chandler Bing:`,-1),c[951]||=i(` Well, she probably wasn’t familiar with the process having spent most of her life sitting for oil paintings!`,-1),c[952]||=a(`blockquote`,null,[a(`p`,null,`嗯，她可能不熟悉这个过程，因为她大部分时间都坐在那里看油画！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/236.mp3`}),c[953]||=i(),c[954]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[955]||=i(` So how did this happen? Did she, did she lure you to an early bird dinner?`,-1),c[956]||=a(`blockquote`,null,[a(`p`,null,`这是怎么发生的？是她，是她引诱你去吃早起的晚餐吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/237.mp3`}),c[957]||=i(),c[958]||=a(`strong`,null,`Ross Geller:`,-1),c[959]||=i(` I was working late in the library one afternoon. It was just the two of us. She needed some help with her word jumble. And one thing led to another. If you must know, Anita was very gentle and tender. May she rest in peace…`,-1),c[960]||=a(`blockquote`,null,[a(`p`,null,`一天下午我在图书馆工作到很晚。只有我们两个人。她需要一些帮助来处理她的单词混乱。一件事导致了另一件事。如果你一定要知道的话，安妮塔非常温柔。愿她安息…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/238.mp3`}),c[961]||=i(),c[962]||=a(`strong`,null,`Monica Geller:`,-1),c[963]||=i(` Didn’t she walk with a cane?`,-1),c[964]||=a(`blockquote`,null,[a(`p`,null,`她不是拄着拐杖走路吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/239.mp3`}),c[965]||=i(),c[966]||=a(`strong`,null,`Ross Geller:`,-1),c[967]||=i(` Only when it was damp!! (To Rachel) I can’t believe you-you told people about this?! Everybody knew?! Y’know what? (To Will) I’m back in the club!`,-1),c[968]||=a(`blockquote`,null,[a(`p`,null,`只有在潮湿的时候！！（对瑞秋）我真不敢相信你告诉别人了？！大家都知道？！你知道吗？（对威尔）我又回到俱乐部了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/240.mp3`}),c[969]||=i(),c[970]||=a(`strong`,null,`Will:`,-1),c[971]||=i(` Yeah! (They high-five.)`,-1),c[972]||=a(`blockquote`,null,[a(`p`,null,`是啊！（他们击掌）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/241.mp3`}),c[973]||=i(),c[974]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[975]||=i(` I wanna join!`,-1),c[976]||=a(`blockquote`,null,[a(`p`,null,`我想加入！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/242.mp3`}),c[977]||=i(),c[978]||=a(`strong`,null,`Rachel Green:`,-1),c[979]||=i(` Wh—Phoebe!!`,-1),c[980]||=a(`blockquote`,null,[a(`p`,null,`菲比！！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/243.mp3`}),c[981]||=i(),c[982]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[983]||=i(` I’m sorry. I’m sorry. I never got to be in a club. I-I didn’t go to high school, but three of us would meet behind a dumpster to learn French. Bonjour.`,-1),c[984]||=a(`blockquote`,null,[a(`p`,null,`对不起。我很抱歉。我从没去过俱乐部。我没有上高中，但我们三个会在垃圾桶后面碰头学法语。你好。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/244.mp3`}),c[985]||=i(),c[986]||=a(`strong`,null,`Rachel Green:`,-1),c[987]||=i(` All right, y’know—Fine! You guys have your stupid little club, but I would just like to say is what you did to me is way worse than what I did to you! You gave me a tiney-wienie! (Will laughs.)`,-1),c[988]||=a(`blockquote`,null,[a(`p`,null,`好吧，你知道，很好！你们有你们愚蠢的小俱乐部，但我想说的是你们对我做的比我对你们做的更糟糕！你给了我一个小维尼！（威尔笑了。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/245.mp3`}),c[989]||=i(),c[990]||=a(`strong`,null,`Monica Geller:`,-1),c[991]||=i(` All right, listen you’re just being silly. Rachel, even with that rumor you were one of the most popular girls in school and everyone wanted to be like you. One girl wanted to be like you so much she stuffed her pants with a Tootsie Roll!`,-1),c[992]||=a(`blockquote`,null,[a(`p`,null,`好吧，听着，你只是在装傻。瑞秋，即使有传言说你是学校里最受欢迎的女孩之一，每个人都想和你一样。一个女孩非常想和你一样，她在裤子里塞满了一个玩具卷！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/246.mp3`}),c[993]||=i(),c[994]||=a(`strong`,null,`Rachel Green:`,-1),c[995]||=i(` Wow…`,-1),c[996]||=a(`blockquote`,null,[a(`p`,null,`哇…`)],-1),r(p,{src:`/audio/friends/S08/S08E09/247.mp3`}),c[997]||=i(),c[998]||=a(`strong`,null,`Monica Geller:`,-1),c[999]||=i(` And Ross, if it weren’t for Rachel’s rumor I mean no one in high school would even know who you were. She put you on the map!`,-1),c[1e3]||=a(`blockquote`,null,[a(`p`,null,`罗斯，如果不是因为瑞秋的谣言，我的意思是高中没人会知道你是谁。她把你放在地图上了！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/248.mp3`}),c[1001]||=i(),c[1002]||=a(`strong`,null,`Ross Geller:`,-1),c[1003]||=i(` As a romancer of the elderly.`,-1),c[1004]||=a(`blockquote`,null,[a(`p`,null,`作为老年人的浪漫主义者。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/249.mp3`}),c[1005]||=i(),c[1006]||=a(`strong`,null,`Monica Geller:`,-1),c[1007]||=i(` Hey! Mrs. Altman was the kind of woman you could tell she used to be pretty.`,-1),c[1008]||=a(`blockquote`,null,[a(`p`,null,`嘿！奥特曼夫人是那种你可以说她以前很漂亮的女人。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/250.mp3`}),c[1009]||=i(),c[1010]||=a(`strong`,null,`Ross Geller:`,-1),c[1011]||=i(` The eyes…did still sparkle.`,-1),c[1012]||=a(`blockquote`,null,[a(`p`,null,`眼睛……还是闪闪发光。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/251.mp3`}),c[1013]||=i(),c[1014]||=a(`strong`,null,`Monica Geller:`,-1),c[1015]||=i(` Hey guys this stuff is just so way in the past. You-you’ve been through so much since then. And right now you’ve got so much more important stuff going on in your life. Can’t you just let this go?`,-1),c[1016]||=a(`blockquote`,null,[a(`p`,null,`嘿，伙计们，这东西过去就是这么回事。从那以后你经历了很多。现在你的生活中有很多更重要的事情。你就不能让这件事过去吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/252.mp3`}),c[1017]||=i(),c[1018]||=a(`strong`,null,`Rachel Green:`,-1),c[1019]||=i(` She’s right.`,-1),c[1020]||=a(`blockquote`,null,[a(`p`,null,`她是对的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/253.mp3`}),c[1021]||=i(),c[1022]||=a(`strong`,null,`Ross Geller:`,-1),c[1023]||=i(` Yeah. I mean we are having a baby together.`,-1),c[1024]||=a(`blockquote`,null,[a(`p`,null,`是的。我是说我们要一起生孩子了。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/254.mp3`}),c[1025]||=i(),c[1026]||=a(`strong`,null,`Will:`,-1),c[1027]||=i(` Hold on! You got her pregnant?`,-1),c[1028]||=a(`blockquote`,null,[a(`p`,null,`等等！你让她怀孕了？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/255.mp3`}),c[1029]||=i(),c[1030]||=a(`strong`,null,`Ross Geller:`,-1),c[1031]||=i(` Yeah.`,-1),c[1032]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/256.mp3`}),c[1033]||=i(),c[1034]||=a(`strong`,null,`Will:`,-1),c[1035]||=i(` Are ya getting married?`,-1),c[1036]||=a(`blockquote`,null,[a(`p`,null,`你要结婚了吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/257.mp3`}),c[1037]||=i(),c[1038]||=a(`strong`,null,`Ross Geller:`,-1),c[1039]||=i(` Nope.`,-1),c[1040]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/258.mp3`}),c[1041]||=i(),c[1042]||=a(`strong`,null,`Will:`,-1),c[1043]||=i(` So you knocked her up but you’re not gonna marry her. Dude! (Wants another high-five and Ross ignores him.) Anybody?`,-1),c[1044]||=a(`blockquote`,null,[a(`p`,null,`所以你把她搞大了，但你不打算娶她。伙计！（想要再击掌，罗斯不理他）有人吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/259.mp3`}),c[1045]||=i(),c[1046]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1047]||=i(` Okay. (Goes over and hugs him.) It’s exactly how I’d imagined it would be.`,-1),c[1048]||=a(`blockquote`,null,[a(`p`,null,`好的。（走过去拥抱他）这正是我所想象的。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/260.mp3`}),c[1049]||=i(),c[1050]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1051]||=i(` (entering, wearing the maternity pants from earlier) All right where’s that turkey!`,-1),c[1052]||=a(`blockquote`,null,[a(`p`,null,`（进来，穿着前面的孕妇裤）好吧，火鸡在哪里！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/261.mp3`}),c[1053]||=i(),c[1054]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1055]||=i(` Joey! Those are my maternity pants!`,-1),c[1056]||=a(`blockquote`,null,[a(`p`,null,`乔伊！那是我的孕妇裤！`)],-1),r(p,{src:`/audio/friends/S08/S08E09/262.mp3`}),c[1057]||=t(` <strong>Joey Tribbiani:</strong> Not now! These are my Thanksgiving pants!<blockquote><p>现在不行！这是我的感恩节长裤！</p></blockquote><p>Closing Credits</p><blockquote><p>片尾字幕</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s, Will has left and the rest of the gang is watching Joey finish the turkey.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒的，威尔已经走了，其他人正在看着乔伊吃完火鸡。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S08/S08E09/263.mp3`}),c[1058]||=i(),c[1059]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1060]||=i(` Well that’s it. I’m done. Whew! (Wipes his forehead.) There come the meat sweats. (Chandler hands him a towel and he wipes his face.)`,-1),c[1061]||=a(`blockquote`,null,[a(`p`,null,`就这样。我做完了。唷！（擦了擦额头）肉出汗了。（钱德勒递给他一条毛巾，他擦了擦脸。）`)],-1),r(p,{src:`/audio/friends/S08/S08E09/264.mp3`}),c[1062]||=i(),c[1063]||=a(`strong`,null,`Monica Geller:`,-1),c[1064]||=i(` Well Joey, we’re all…we’re all very proud of you.`,-1),c[1065]||=a(`blockquote`,null,[a(`p`,null,`乔伊，我们都…我们都为你感到骄傲。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/265.mp3`}),c[1066]||=i(),c[1067]||=a(`strong`,null,`Chandler Bing:`,-1),c[1068]||=i(` Yes, I believe we can expect a call from the President any moment now.`,-1),c[1069]||=a(`blockquote`,null,[a(`p`,null,`是的，我相信总统随时都会给我们打电话。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/266.mp3`}),c[1070]||=i(),c[1071]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[1072]||=i(` Is there anything we can do for you?`,-1),c[1073]||=a(`blockquote`,null,[a(`p`,null,`我们能为你做点什么吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/267.mp3`}),c[1074]||=i(),c[1075]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1076]||=i(` No just, nobody press on my stomach.`,-1),c[1077]||=a(`blockquote`,null,[a(`p`,null,`不，只是，没人按我的肚子。`)],-1),r(p,{src:`/audio/friends/S08/S08E09/268.mp3`}),c[1078]||=i(),c[1079]||=a(`strong`,null,`Rachel Green:`,-1),c[1080]||=i(` You can keep those pants by the way.`,-1),c[1081]||=a(`blockquote`,null,[a(`p`,null,`顺便说一下，你可以留着那条裤子。`)],-1),c[1082]||=a(`p`,null,[a(`em`,null,`(Joey notices Monica has gotten a pie.)`)],-1),c[1083]||=a(`blockquote`,null,[a(`p`,null,[a(`em`,null,`（乔伊注意到莫妮卡得到了一个派。）`)])],-1),r(p,{src:`/audio/friends/S08/S08E09/269.mp3`}),c[1084]||=i(),c[1085]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1086]||=i(` Whoa—hey—wh-wh-what do you got there? What is that? Pie?`,-1),c[1087]||=a(`blockquote`,null,[a(`p`,null,`哇，嘿，哇，你拿了什么？那是什么？馅饼`)],-1),r(p,{src:`/audio/friends/S08/S08E09/270.mp3`}),c[1088]||=i(),c[1089]||=a(`strong`,null,`Monica Geller:`,-1),c[1090]||=i(` Yeah, you want some?`,-1),c[1091]||=a(`blockquote`,null,[a(`p`,null,`是的，你想要一些吗？`)],-1),r(p,{src:`/audio/friends/S08/S08E09/271.mp3`}),c[1092]||=i(),c[1093]||=a(`strong`,null,`Joey Tribbiani:`,-1),c[1094]||=i(` Ah, just cut me a little sliver. (Monica prepares to cut a little sliver.) A little bigger. (Monica prepares to cut a bigger piece.) Little bigger. (Monica moves the knife again.) What?! Are you afraid you’re gonna run out?! Cut me a real piece!`,-1),c[1095]||=a(`blockquote`,null,[a(`p`,null,`啊，给我切一点吧。（莫妮卡准备切一小块）再大一点。（莫妮卡准备切一块更大的）再大一点。（莫妮卡又动刀子）什么？！你害怕你会跑出去吗？！给我切一块真的！`)],-1)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};